<template>
  <section class="radar-page recruitment-radar"><div class="radar-heading"><div><p class="eyebrow">COMPETITOR CAMPUS INTELLIGENCE · 演示数据</p><h1>今日校招雷达</h1><p>竞品校招节奏总时间线：启动、宣讲、笔试与 offer 关键节点。</p></div><div class="radar-heading-actions"><span class="source-legend"><i class="green-dot"></i>官方来源 <i class="blue-dot"></i>权威媒体 <i class="gray-dot"></i>待核验</span><button class="primary-btn" @click="$emit('brief')">✦ 生成雷达简报</button></div></div><div class="radar-note"><span>自动监测为主</span><p>校招启动、宣讲等节点来自公开渠道模拟监测；点击节点可查看对应公司官网或公众号来源。</p><b>未来 7 天动态 <strong>{{ upcomingCount }}</strong></b></div><div class="timeline-panel panel"><div class="timeline-head"><div><div class="section-label"><span class="section-mark orange-mark"></span>竞品节奏总览</div><h2>保险 · 金融 · 互联网</h2></div><div class="timeline-range"><button v-for="item in ranges" :key="item" :class="{ selected: range === item }" @click="range = item">{{ item }}</button></div></div><div class="timeline-scroll"><div class="timeline-axis"><span v-for="day in days" :key="day.date" :class="{ today: day.today }"><b>{{ day.label }}</b><small>{{ day.date }}</small></span></div><section v-for="group in groupedCompanies" :key="group.name" class="timeline-group"><div class="group-title"><span class="group-index">{{ group.index }}</span><div><b>{{ group.name }}</b><small>{{ group.description }}</small></div></div><div class="company-lanes"><div v-for="company in group.companies" :key="company.name" class="company-lane"><button class="company-name" @click="selectedCompany = selectedCompany === company.name ? '' : company.name"><span v-if="company.upcoming" class="upcoming-dot"></span>{{ company.name }}<em>{{ company.events.length }}</em></button><div class="lane-track"><span class="lane-line"></span><button v-for="event in company.events" :key="event.id" :class="['timeline-node', event.tone]" :style="{ left: event.left + '%' }" :title="event.title" @click="openNode(event)"><i>{{ event.kind }}</i><b>{{ event.title }}</b></button></div><div v-if="selectedCompany === company.name" class="company-pop"><strong>{{ company.name }} · 近期节点</strong><span v-for="event in company.events" :key="event.id">{{ event.date }} {{ event.title }} <a @click="openNode(event)">查看来源</a></span></div></div></div></section></div><div class="timeline-foot"><span><i class="timeline-key orange-key"></i>校招节点 <i class="timeline-key purple-key"></i>招聘节奏变化 <i class="timeline-key blue-key"></i>待核验</span><span>点击公司名称查看详情 · 点击节点查看来源</span></div></div><div class="radar-bottom-grid"><div class="panel group-summary"><div class="panel-head compact"><div><div class="section-label"><span class="section-mark purple-mark"></span>分组逻辑</div><h2>竞品观察范围</h2></div><span class="demo-label">模拟口径</span></div><div v-for="group in groupedCompanies" :key="group.name" class="summary-row"><span class="summary-badge">{{ group.index }}</span><div><b>{{ group.name }}</b><p>{{ group.description }}</p></div><strong>{{ group.companies.length }} 家</strong></div></div><div class="panel source-panel"><div class="panel-head compact"><div><div class="section-label"><span class="section-mark blue-mark"></span>数据来源规范</div><h2>每条信息都标注来源</h2></div><span class="demo-label">自动监测为主</span></div><div class="source-rules"><div><i class="green-dot"></i><span>绿色</span><p>公司官网 / 官方公众号 / 校招官网</p></div><div><i class="blue-dot"></i><span>蓝色</span><p>权威媒体报道</p></div><div><i class="gray-dot"></i><span>灰色</span><p>其他渠道，需人工复核</p></div></div><div class="source-caption">演示数据 · 正式上线前补充可追溯来源</div></div></div></section>
</template>
<script>
export default { name: 'RecruitmentRadar', props: { companies: Array }, data () { return { range: '近 30 天', ranges: ['近 7 天', '近 30 天', '本季度'], selectedCompany: '' } }, computed: { days () { return [{ label: '10月', date: '21', today: false }, { label: '10月', date: '24', today: false }, { label: '10月', date: '26', today: true }, { label: '10月', date: '29', today: false }, { label: '11月', date: '02', today: false }, { label: '11月', date: '06', today: false }, { label: '11月', date: '10', today: false }, { label: '11月', date: '14', today: false }] }, groupedCompanies () { var definitions = [{ index: '01', name: '保险竞品', description: '国寿 / 平安 / 人保 / 太保 / 友邦 / 泰康', names: ['中国人寿', '中国平安', '中国人保', '中国太保', '友邦保险', '泰康保险'] }, { index: '02', name: '头部金融机构', description: '银行总行 / 基金 / 证券：招行 / 华泰 / 广发 / 中金', names: ['招商银行', '华泰证券', '广发证券', '中金公司'] }, { index: '03', name: '头部互联网大厂', description: '字节 / 腾讯 / 阿里 / 京东 / 华为', names: ['字节跳动', '腾讯', '阿里巴巴', '京东', '华为'] }]; return definitions.map(function (group) { return { index: group.index, name: group.name, description: group.description, companies: group.names.map(function (name, companyIndex) { var base = (companyIndex * 2 + group.index * 3) % 8; var events = [{ id: name + '-start', date: '10/' + (22 + base), kind: '启动', title: '校招启动', left: 7 + base * 3, tone: 'orange', url: '#' }, { id: name + '-talk', date: '10/' + (26 + base), kind: '宣讲', title: '校园宣讲', left: 22 + base * 4, tone: 'purple', url: '#' }, { id: name + '-test', date: '11/' + (2 + base % 5), kind: '笔试', title: '统一笔试', left: 52 + base * 3, tone: 'blue', url: '#' }, { id: name + '-offer', date: '11/' + (8 + base % 5), kind: 'offer', title: '首批 offer', left: 77 + base * 2, tone: 'green', url: '#' }]; return { name: name, upcoming: companyIndex % 2 === 0 || group.index === '03', events: events } }) } }) }, upcomingCount () { return this.groupedCompanies.reduce(function (sum, group) { return sum + group.companies.filter(function (item) { return item.upcoming }).length }, 0) } }, methods: { openNode (event) { this.$emit('source', event) } } }
</script>



